def get_flood_fill_regions(grid, target_value):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    regions = []

    for i in range(h):
        for j in range(w):
            if grid[i][j] == target_value and not visited[i][j]:
                region = []
                queue = [(i, j)]
                visited[i][j] = True
                while queue:
                    r, c = queue.pop(0)
                    region.append((r, c))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == target_value and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                regions.append(region)

    return regions

